<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import { calc, rupiah, rupiahInput } from '../../composables/costing';
type Cost = { id_rate: number | null; tipe: 'fixed' | 'variable'; item: string; id_satuan: number; nama_satuan: string | null; harga: number | string; is_manual: number | boolean };
type Program = { id: number | null; nomor: string; status: string; closed_date: string | null; jenis: string; id_master_program: number | ''; id_customer: string; id_trainer: number | ''; id_asisten: number | ''; tgl_mulai: string; tgl_selesai: string; waktu: string; lokasi: string; jam_pembelajaran: number | string; durasi_hari: number; target_peserta: number; harga_jual_peserta: number | string; target_profit: number | string; biaya: Cost[] };
type Master = { id: number; nomor: string; judul: string; jam_pembelajaran: number; target_peserta: number; harga_jual_peserta: string; target_profit: string; biaya: Cost[] };
type Rate = { id: number; tipe: 'fixed' | 'variable'; item: string; id_satuan: number; nama_satuan: string; default_cost: string };
type Actual = { total_hpp: number; pendapatan: number; profit: number; margin: number };
const props = defineProps<{ program: Program; masters: Master[]; companies: { id_customer: string; name_customer: string }[]; trainers: { id: number; nama: string }[]; assistants: { id: number; nama: string; role: string | null }[]; rates: Rate[]; units: { id: number; nama: string }[]; can: { edit: boolean; approve: boolean; cancel: boolean }; actual: { peserta: number; rencana: Actual; aktual: Actual } | null }>();
const form = useForm({ ...props.program, harga_jual_peserta: Math.round(Number(props.program.harga_jual_peserta)), target_profit: Math.round(Number(props.program.target_profit)), biaya: props.program.biaya.map((b) => ({ ...b, harga: Math.round(Number(b.harga)) })) as Cost[] });
const editable = props.program.status === 'draft' && !props.program.closed_date && props.can.edit;
const errors = computed(() => Object.values(form.errors));
const choiceSearch = ref('');
const matches = (label: string) => label.toLocaleLowerCase('id-ID').includes(choiceSearch.value.toLocaleLowerCase('id-ID'));
function source() {
    const m = props.masters.find((m) => m.id === Number(form.id_master_program));
    if (!m || props.program.id) return;
    form.jam_pembelajaran = m.jam_pembelajaran; form.target_peserta = m.target_peserta;
    form.harga_jual_peserta = Math.round(Number(m.harga_jual_peserta)); form.target_profit = Math.round(Number(m.target_profit));
    form.biaya = m.biaya.map((b) => ({ ...b, harga: Math.round(Number(b.harga)) }));
}
const days = computed(() => Math.max(1, (Date.parse(form.tgl_selesai) - Date.parse(form.tgl_mulai)) / 86400000 + 1 || 1));
const result = computed(() => calc(days.value, form.target_peserta, rupiahInput(form.harga_jual_peserta), form.biaya.map((b) => ({ ...b, harga: rupiahInput(b.harga), satuan: b.nama_satuan }))));
const pick = ref('');
function addRate() {
    const r = props.rates.find((r) => r.id === Number(pick.value)); if (!r) return;
    form.biaya.push({ id_rate: r.id, tipe: r.tipe, item: r.item, id_satuan: r.id_satuan, nama_satuan: r.nama_satuan, harga: Math.round(Number(r.default_cost)), is_manual: false }); pick.value = '';
}
function unit(b: Cost) { b.nama_satuan = props.units.find((u) => u.id === Number(b.id_satuan))?.nama ?? null; }
function save() { if (props.program.id) form.put(`/penjualan-program/${props.program.id}`, { preserveState: 'errors' }); else form.post('/penjualan-program', { preserveState: 'errors' }); }
const action = ref(''); const transition = useForm({});
function status() { transition.post(`/penjualan-program/${props.program.id}/${action.value}`, { preserveState: 'errors', onSuccess: () => { action.value = ''; } }); }
</script>
<template>
    <Head :title="program.nomor || 'Buat Penjualan Program'" /><AppLayout title="Penjualan Program">
        <div class="page-head"><h1>{{ program.nomor || 'Buat Penjualan Program' }}</h1><span class="badge">{{ program.status }}{{ program.closed_date ? ' · Closed' : '' }}</span></div>
        <ul v-if="errors.length" class="error" role="alert"><li v-for="e in errors" :key="e">{{ e }}</li></ul>
        <p v-if="program.id && program.status === 'final'"><Link :href="`/penjualan-program/${program.id}/reschedule`">Reschedule / Riwayat</Link></p><form class="stack" @submit.prevent="save"><fieldset :disabled="!editable || form.processing" class="panel"><legend>Program dan jadwal</legend><label v-if="editable">Cari pilihan program, Company, trainer, atau asisten<input v-model="choiceSearch" type="search" maxlength="100" /></label><div class="form-grid">
            <label>Jenis<select v-model="form.jenis" :disabled="!!program.id"><option value="public">Public</option><option value="b2b">B2B</option></select></label>
            <label>Master Program Final<select v-model="form.id_master_program" required :disabled="!!program.id" @change="source"><option value="">Pilih</option><option v-for="m in masters.filter((m) => m.id === Number(form.id_master_program) || matches(m.nomor + ' ' + m.judul))" :key="m.id" :value="m.id">{{ m.nomor }} · {{ m.judul }}</option></select></label>
            <label v-if="form.jenis === 'b2b'">Company<select v-model="form.id_customer" required><option value="">Pilih Company aktif</option><option v-for="c in companies.filter((c) => c.id_customer === form.id_customer || matches(c.name_customer))" :key="c.id_customer" :value="c.id_customer">{{ c.name_customer }}</option></select></label>
            <label>Trainer<select v-model="form.id_trainer" required><option value="">Pilih trainer aktif</option><option v-for="t in trainers.filter((t) => t.id === Number(form.id_trainer) || matches(t.nama))" :key="t.id" :value="t.id">{{ t.nama }}</option></select></label>
            <label>Asisten trainer<select v-model="form.id_asisten" required><option value="">Pilih asisten aktif</option><option v-for="a in assistants.filter((a) => a.id === Number(form.id_asisten) || matches(a.nama + ' ' + (a.role ?? '')))" :key="a.id" :value="a.id">{{ a.nama }}{{ a.role ? ' · ' + a.role : '' }}</option></select></label>
            <label>Tanggal mulai<input v-model="form.tgl_mulai" type="date" required /></label><label>Tanggal selesai<input v-model="form.tgl_selesai" type="date" :min="form.tgl_mulai" required /></label>
            <label>Waktu<input v-model="form.waktu" maxlength="50" /></label><label>Lokasi<input v-model="form.lokasi" maxlength="150" /></label><label>Jam Pembelajaran (JP)<input v-model="form.jam_pembelajaran" type="number" min="1" required /></label>
            <label>Target peserta<input v-model="form.target_peserta" type="number" :min="form.jenis === 'b2b' ? 10 : 1" required /></label><label>Harga jual / peserta (Rp)<input v-model="form.harga_jual_peserta" inputmode="numeric" required /></label><label>Target profit (Rp)<input v-model="form.target_profit" inputmode="numeric" /></label>
        </div><p>Durasi: {{ days }} hari.</p></fieldset>
        <fieldset :disabled="!editable || form.processing" class="panel"><legend>Biaya penjualan</legend><div class="table-wrap"><table><thead><tr><th>Item</th><th>Tipe</th><th>Satuan</th><th>Nominal (Rp)</th><th>Aksi</th></tr></thead><tbody>
            <tr v-for="(b, i) in form.biaya" :key="i"><td><input v-if="b.is_manual" v-model="b.item" :aria-label="`Item ${i + 1}`" maxlength="150" required /><span v-else>{{ b.item }}</span></td><td><select v-if="b.is_manual" v-model="b.tipe" :aria-label="`Tipe ${i + 1}`" @change="b.id_satuan = 0; b.nama_satuan = null"><option value="fixed">Fixed</option><option value="variable">Variable</option></select><span v-else>{{ b.tipe }}</span></td><td><select v-if="b.is_manual" v-model="b.id_satuan" :aria-label="`Satuan ${i + 1}`" required @change="unit(b)"><option :value="0">Pilih</option><option v-for="u in units.filter((u) => (b.tipe === 'fixed' ? ['Event', 'Day'] : ['Peserta/Event', 'Peserta/Day']).includes(u.nama))" :key="u.id" :value="u.id">{{ u.nama }}</option></select><span v-else>{{ b.nama_satuan }}</span></td><td><input v-model="b.harga" inputmode="numeric" :aria-label="`Nominal ${b.item}`" required /></td><td><button v-if="editable" type="button" class="danger" @click="form.biaya.splice(i, 1)">Hapus</button></td></tr>
            <tr v-if="!form.biaya.length"><td colspan="5" class="empty">Belum ada biaya.</td></tr>
        </tbody></table></div><div v-if="editable" class="filters"><label>Master Rate<select v-model="pick" @change="addRate"><option value="">Pilih</option><option v-for="r in rates.filter((r) => !form.biaya.some((b) => b.id_rate === r.id))" :key="r.id" :value="r.id">{{ r.item }} · {{ r.nama_satuan }}</option></select></label><button type="button" @click="form.biaya.push({ id_rate: null, tipe: 'fixed', item: '', id_satuan: 0, nama_satuan: null, harga: '', is_manual: true })">Tambah biaya lain</button></div></fieldset>
        <section class="panel"><h2>Simulasi</h2><dl><dt>HPP</dt><dd>{{ rupiah(result.hpp) }}</dd><dt>Pendapatan</dt><dd>{{ rupiah(result.pendapatan) }}</dd><dt>Profit</dt><dd>{{ rupiah(result.profit) }} ({{ result.margin }}%)</dd><dt>BEP</dt><dd>{{ result.bep ?? 'Tidak tercapai' }} peserta</dd></dl><p v-if="result.profit < 0 || (result.bep ?? Infinity) > Number(form.target_peserta)" class="notice">Target belum mencapai titik impas.</p></section>
        <div class="form-actions"><button v-if="editable" class="primary" :disabled="form.processing">{{ form.processing ? 'Menyimpan…' : 'Simpan Draft' }}</button><button v-if="program.id && program.status === 'draft' && can.approve" type="button" @click="action = 'finalkan'">Finalkan</button><button v-if="program.id && program.status === 'draft' && can.cancel" type="button" class="danger" @click="action = 'batalkan'">Batalkan</button><Link href="/penjualan-program">Kembali</Link><Link v-if="program.status === 'final'" :href="`/quotation/batch/${program.id}`">Quotation</Link><a v-if="program.status === 'final'" :href="`/penjualan-program/${program.id}/pdf`" target="_blank" rel="noopener">Cetak penawaran</a></div></form>
        <section v-if="actual" class="panel"><h2>Rencana vs Aktual</h2><p>Aktual berdasarkan {{ actual.peserta }} peserta Deal dan harga Penjualan Program.</p><div class="table-wrap"><table><thead><tr><th>Perhitungan</th><th>Rencana</th><th>Aktual</th><th>Selisih</th></tr></thead><tbody><tr><th>Peserta</th><td>{{ program.target_peserta }}</td><td>{{ actual.peserta }}</td><td>{{ actual.peserta - program.target_peserta }}</td></tr><tr v-for="[field, label] in ([['total_hpp', 'HPP'], ['pendapatan', 'Pendapatan'], ['profit', 'Profit']] as const)" :key="field"><th>{{ label }}</th><td>{{ rupiah(actual.rencana[field]) }}</td><td>{{ rupiah(actual.aktual[field]) }}</td><td>{{ rupiah(actual.aktual[field] - actual.rencana[field]) }}</td></tr></tbody></table></div></section>
        <ConfirmDialog v-if="action" :title="action === 'finalkan' ? 'Finalkan Penjualan Program?' : 'Batalkan Penjualan Program?'" :confirm-label="action === 'finalkan' ? 'Finalkan' : 'Batalkan'" :busy="transition.processing" @cancel="action = ''" @confirm="status"><p>Setelah diproses, Draft terkunci.</p><template v-if="action === 'finalkan'"><p>{{ form.jenis.toUpperCase() }} · {{ days }} hari · {{ form.target_peserta }} peserta · {{ rupiah(rupiahInput(form.harga_jual_peserta)) }} / peserta.</p><p>Pendapatan {{ rupiah(result.pendapatan) }} · HPP {{ rupiah(result.hpp) }} · Profit {{ rupiah(result.profit) }} · BEP {{ result.bep ?? 'tidak tercapai' }} peserta.</p><p v-if="result.profit < 0 || (result.bep ?? Infinity) > Number(form.target_peserta)" class="notice">Target belum mencapai titik impas. Finalkan tetap dapat dilanjutkan.</p></template><p v-for="e in transition.errors" :key="e" class="error" role="alert">{{ e }}</p></ConfirmDialog>
    </AppLayout>
</template>
